import { Sprite, SpriteMaterial, Group } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Position from config (if provided, otherwise default)
  if (config.position) {
    group.position.set(config.position.x, config.position.y, config.position.z);
  } else {
    group.position.set(-3.2, 1, 0.06);
  }
  if (config.rotation) {
    group.rotation.set(config.rotation.x, config.rotation.y, config.rotation.z);
  }
  if (config.scale) {
    group.scale.set(config.scale.x, config.scale.y, config.scale.z);
  }

  // --- Text content ---
  const items = config.textContent ?? [];
  const headline = items.find(i => i.role && i.role.includes('headline')) || 
                   items[0] || 
                   { text: 'Collection 1', typography: { fontSize: 39 } };

  const text = ctx.fontAtlas.createText(headline.text, {
    fontSize: headline.typography?.fontSize || 39,
    color: '#e8ecf2',
    align: 'center',
  });
  text.position.z = 0.02; // slightly forward to avoid z-fighting once sprite is added
  group.add(text);

  // --- Sprite plane (billboarded) ---
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      const mat = new SpriteMaterial({
        map: tex,
        transparent: true,
        depthTest: true,
      });
      const sprite = new Sprite(mat);

      // Set size to match texture’s aspect ratio (source rect: 512×320 → 1.6:1)
      const aspect = tex.image ? (tex.image.width / tex.image.height) : 1.6;
      sprite.scale.set(aspect, 1, 1);
      group.add(sprite);
    }).catch(err => console.warn(`[CollectionCard1] Texture load failed: ${err}`));
  }

  // --- No cinematic primitives ---

  // --- Event handlers ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Dispose all materials, textures, geometries owned by this node
    group.traverse((child) => {
      if (child.isSprite && child.material) {
        child.material.map?.dispose();
        child.material.dispose();
      }
      if (child.isMesh && child.material) {
        // text mesh (uses font atlas – we only dispose the geometry, not the shared font texture)
        child.geometry?.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
    // Kill any GSAP timelines (none in this node)
    // (no timelines to kill)
  };

  return group;
}
